from typing import List

class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        groups = []
        for word in strs:
            placed = False
            for group in groups:
                if sorted(word) == sorted(group[0]):
                    group.append(word)
                    placed = True
                    break
            if not placed:
                groups.append([word])
        return groups

